from __future__ import annotations

import random
from dataclasses import dataclass
from math import ceil, sqrt

from .allocation import allocate_from_global_pool
from .models import DemandSeries, InventoryPosition, Network, PoolSupply
from .replenishment import build_replenishment_recommendations, round_up_to_pack

# Default seed keeps the strategy comparison reproducible (tests assert a stable
# ordering) while the demand path itself is generated by a random process rather
# than a fixed formula. Pass a different seed to observe a different realisation.
DEFAULT_DEMAND_SEED = 20240601


@dataclass(frozen=True)
class SimulationMetrics:
    strategy: str
    days: int
    total_demand_units: int
    fulfilled_units: int
    stockout_units: int
    fill_rate: float
    stockout_rate: float
    average_delivery_days: float
    average_inventory_units: float
    inventory_turnover_days: float
    replenishment_cost: float
    transfer_cost: float
    holding_cost: float
    lost_sales_penalty: float
    total_profit: float


@dataclass(frozen=True)
class SimulationComparison:
    days: int
    baseline: SimulationMetrics
    intelligent: SimulationMetrics
    improvement: dict[str, float]
    interpretation: str


def compare_strategies(
    network: Network,
    days: int = 90,
    planning_interval_days: int = 7,
    horizon_days: int = 30,
    demand_seed: int = DEFAULT_DEMAND_SEED,
) -> SimulationComparison:
    demand_calendar = _build_actual_demand_calendar(network, days, demand_seed)
    baseline = _simulate_baseline(network, demand_calendar, days, planning_interval_days, horizon_days)
    intelligent = _simulate_intelligent(network, demand_calendar, days, planning_interval_days, horizon_days)
    improvement = {
        "fill_rate_lift_pct": round((intelligent.fill_rate - baseline.fill_rate) * 100, 2),
        "stockout_rate_reduction_pct": round((baseline.stockout_rate - intelligent.stockout_rate) * 100, 2),
        "inventory_reduction_units": round(baseline.average_inventory_units - intelligent.average_inventory_units, 2),
        "delivery_days_reduction": round(baseline.average_delivery_days - intelligent.average_delivery_days, 2),
        "profit_lift": round(intelligent.total_profit - baseline.total_profit, 2),
    }
    if improvement["inventory_reduction_units"] >= 0:
        inventory_phrase = "同时压降平均库存"
    else:
        inventory_phrase = "在提高安全库存投入的同时提升供货稳定性"
    interpretation = (
        "智能方案通过全球库存池、跨仓履约和滚动补货，把预测结果转成库存动作；"
        f"与传统各仓独立备货相比，可降低缺货、改善履约时效，并{inventory_phrase}。"
    )
    return SimulationComparison(
        days=days,
        baseline=baseline,
        intelligent=intelligent,
        improvement=improvement,
        interpretation=interpretation,
    )


def _build_actual_demand_calendar(
    network: Network, days: int, seed: int = DEFAULT_DEMAND_SEED
) -> dict[tuple[str, str], list[int]]:
    """Generate the realised daily-demand path with a random process.

    Instead of a fixed formula, each day's demand is *sampled* from the
    statistics of the series' own history (mean level and dispersion), then
    modulated by the same weekday / promotion / trend signals the live sandbox
    uses and perturbed by Poisson-Gamma noise. Both strategies in
    :func:`compare_strategies` consume the same calendar, so the comparison
    stays fair; the seed makes a given realisation reproducible.
    """
    calendar: dict[tuple[str, str], list[int]] = {}
    for series in network.demand_history:
        source_values = series.daily_units[-days:] if len(series.daily_units) >= days else series.daily_units
        base_level, dispersion = _series_statistics(source_values)
        # Per-series stream so adding/removing a series does not shift the draws
        # of the others, and the whole calendar is reproducible from the seed.
        rng = random.Random(f"{seed}:{series.sku}:{series.warehouse_id}")
        values: list[int] = []
        for day in range(days):
            weekly_factor = 1.12 if day % 7 in (4, 5) else 0.96 if day % 7 == 0 else 1.0
            promo_factor = _promotion_factor(day, rng)
            trend_factor = 1 + day * 0.0025
            expected = base_level * weekly_factor * promo_factor * trend_factor
            values.append(_sample_demand(expected, dispersion, rng))
        calendar[(series.sku, series.warehouse_id)] = values
    return calendar


def _series_statistics(history: list[int]) -> tuple[float, float]:
    """Mean level and coefficient of variation estimated from real history."""
    if not history:
        return 0.0, 0.0
    mean = sum(history) / len(history)
    if mean <= 0:
        return 0.0, 0.0
    variance = sum((value - mean) ** 2 for value in history) / len(history)
    # Clamp dispersion to a realistic band: enough to show day-to-day variation,
    # not so wild that a single draw dominates a 90-day run.
    cv = min(0.6, max(0.18, sqrt(variance) / mean))
    return mean, cv


def _promotion_factor(day: int, rng: random.Random) -> float:
    """Stochastic promotion lift. Campaign windows fire more often and harder,
    but a baseline day still has a small chance of an organic spike."""
    in_campaign_window = day % 30 in (24, 25, 26, 27)
    probability = 0.62 if in_campaign_window else 0.06
    if rng.random() >= probability:
        return 1.0
    return rng.uniform(1.25, 1.55) if in_campaign_window else rng.uniform(1.1, 1.3)


def _sample_demand(expected: float, cv: float, rng: random.Random) -> int:
    """Draw an integer demand around ``expected`` using a Gamma-mixed Poisson
    (negative-binomial) process, which reproduces the over-dispersed, bursty
    counts seen in real order streams better than a plain Poisson."""
    if expected <= 0:
        return 0
    if cv <= 0:
        return max(0, round(rng.gauss(expected, sqrt(expected))))
    # Gamma shape/scale chosen so the latent rate has mean ``expected`` and the
    # given coefficient of variation; Poisson on top adds counting noise.
    shape = 1.0 / (cv * cv)
    rate = rng.gammavariate(shape, expected / shape)
    return _poisson(rate, rng)


def _poisson(mean: float, rng: random.Random) -> int:
    """Sample a Poisson count. Knuth's method for small means, a Gaussian
    approximation for large means to avoid the multiplicative loop blowing up."""
    if mean <= 0:
        return 0
    if mean > 80:
        return max(0, round(rng.gauss(mean, sqrt(mean))))
    threshold = pow(2.718281828459045, -mean)
    count = 0
    product = rng.random()
    while product > threshold:
        count += 1
        product *= rng.random()
    return count


def _simulate_baseline(
    network: Network,
    demand_calendar: dict[tuple[str, str], list[int]],
    days: int,
    planning_interval_days: int,
    horizon_days: int,
) -> SimulationMetrics:
    return _simulate(
        strategy="传统独立备货",
        network=network,
        demand_calendar=demand_calendar,
        days=days,
        planning_interval_days=planning_interval_days,
        horizon_days=horizon_days,
        use_pool_optimization=False,
        allow_cross_fulfillment=False,
    )


def _simulate_intelligent(
    network: Network,
    demand_calendar: dict[tuple[str, str], list[int]],
    days: int,
    planning_interval_days: int,
    horizon_days: int,
) -> SimulationMetrics:
    return _simulate(
        strategy="智能库存池方案",
        network=network,
        demand_calendar=demand_calendar,
        days=days,
        planning_interval_days=planning_interval_days,
        horizon_days=horizon_days,
        use_pool_optimization=True,
        allow_cross_fulfillment=True,
    )


def _simulate(
    strategy: str,
    network: Network,
    demand_calendar: dict[tuple[str, str], list[int]],
    days: int,
    planning_interval_days: int,
    horizon_days: int,
    use_pool_optimization: bool,
    allow_cross_fulfillment: bool,
) -> SimulationMetrics:
    inventory = {(item.sku, item.warehouse_id): item.on_hand for item in network.inventory.values()}
    inbound: list[tuple[int, str, str, int, float]] = []

    total_demand = 0
    fulfilled = 0
    stockout = 0
    delivery_days = 0.0
    replenishment_cost = 0.0
    transfer_cost = 0.0
    lost_sales_penalty = 0.0
    holding_cost = 0.0
    gross_margin = 0.0
    inventory_sum = 0

    for day in range(days):
        arrivals = [item for item in inbound if item[0] == day]
        inbound = [item for item in inbound if item[0] != day]
        for _, sku, warehouse_id, units, cost in arrivals:
            inventory[(sku, warehouse_id)] += units
            replenishment_cost += cost

        if day % planning_interval_days == 0:
            if use_pool_optimization:
                inbound.extend(_plan_intelligent_replenishment(network, inventory, inbound, day, horizon_days, demand_calendar))
            else:
                inbound.extend(_plan_baseline_replenishment(network, inventory, inbound, day, horizon_days))

        for key, values in demand_calendar.items():
            sku_id, warehouse_id = key
            demand_units = values[day]
            if demand_units <= 0:
                continue

            sku = network.skus[sku_id]
            total_demand += demand_units
            local_fulfilled = min(inventory[key], demand_units)
            inventory[key] -= local_fulfilled
            fulfilled += local_fulfilled
            gross_margin += local_fulfilled * sku.unit_margin
            delivery_days += local_fulfilled * _local_delivery_days(network, warehouse_id)
            remaining = demand_units - local_fulfilled

            if allow_cross_fulfillment and remaining > 0:
                cross_fulfilled, cross_delivery, cross_cost = _fulfill_from_alternate_warehouses(
                    network=network,
                    inventory=inventory,
                    sku_id=sku_id,
                    target_warehouse_id=warehouse_id,
                    required_units=remaining,
                )
                fulfilled += cross_fulfilled
                gross_margin += cross_fulfilled * sku.unit_margin
                delivery_days += cross_delivery
                transfer_cost += cross_cost
                remaining -= cross_fulfilled

            if remaining > 0:
                stockout += remaining
                lost_sales_penalty += remaining * sku.unit_margin
                delivery_days += remaining * 10.0

        daily_inventory = sum(max(0, units) for units in inventory.values())
        inventory_sum += daily_inventory
        holding_cost += daily_inventory * 0.08

    average_inventory = inventory_sum / max(1, days)
    average_daily_fulfilled = fulfilled / max(1, days)
    turnover_days = average_inventory / max(1, average_daily_fulfilled)
    total_profit = gross_margin - replenishment_cost - transfer_cost - holding_cost - lost_sales_penalty

    return SimulationMetrics(
        strategy=strategy,
        days=days,
        total_demand_units=total_demand,
        fulfilled_units=fulfilled,
        stockout_units=stockout,
        fill_rate=round(fulfilled / max(1, total_demand), 4),
        stockout_rate=round(stockout / max(1, total_demand), 4),
        average_delivery_days=round(delivery_days / max(1, total_demand), 2),
        average_inventory_units=round(average_inventory, 2),
        inventory_turnover_days=round(turnover_days, 2),
        replenishment_cost=round(replenishment_cost, 2),
        transfer_cost=round(transfer_cost, 2),
        holding_cost=round(holding_cost, 2),
        lost_sales_penalty=round(lost_sales_penalty, 2),
        total_profit=round(total_profit, 2),
    )


def _plan_baseline_replenishment(
    network: Network,
    inventory: dict[tuple[str, str], int],
    inbound: list[tuple[int, str, str, int, float]],
    day: int,
    horizon_days: int,
) -> list[tuple[int, str, str, int, float]]:
    planned: list[tuple[int, str, str, int, float]] = []
    inbound_units = _inbound_units(inbound)

    for series in network.demand_history:
        sku = network.skus[series.sku]
        lane = network.lane_from_pool(series.warehouse_id)
        if lane is None:
            continue
        recent_average = sum(series.daily_units[-14:]) / min(14, len(series.daily_units))
        fixed_safety = recent_average * 14
        target_stock = ceil(recent_average * max(horizon_days, lane.lead_time_days) + fixed_safety)
        key = (series.sku, series.warehouse_id)
        need = target_stock - inventory[key] - inbound_units.get(key, 0)
        units = round_up_to_pack(max(0, need), sku.pack_size)
        if units > 0:
            manual_approval_delay_days = 7
            planned.append(
                (
                    day + lane.lead_time_days + manual_approval_delay_days,
                    series.sku,
                    series.warehouse_id,
                    units,
                    units * lane.unit_cost,
                )
            )

    return planned


def _plan_intelligent_replenishment(
    network: Network,
    inventory: dict[tuple[str, str], int],
    inbound: list[tuple[int, str, str, int, float]],
    day: int,
    horizon_days: int,
    demand_calendar: dict[tuple[str, str], list[int]],
) -> list[tuple[int, str, str, int, float]]:
    planning_network = _network_snapshot(network, inventory, inbound, day, demand_calendar)
    recommendations = build_replenishment_recommendations(planning_network, horizon_days=horizon_days)
    allocations = allocate_from_global_pool(planning_network, recommendations)
    planned: list[tuple[int, str, str, int, float]] = []

    for decision in allocations:
        if decision.allocated_units <= 0:
            continue
        lane = network.lane_from_pool(decision.warehouse_id)
        if lane is None:
            continue
        planned.append(
            (
                day + max(1, decision.lead_time_days),
                decision.sku,
                decision.warehouse_id,
                decision.allocated_units,
                decision.allocated_units * lane.unit_cost,
            )
        )

    return planned


def _network_snapshot(
    network: Network,
    inventory: dict[tuple[str, str], int],
    inbound: list[tuple[int, str, str, int, float]],
    day: int,
    demand_calendar: dict[tuple[str, str], list[int]],
) -> Network:
    inbound_units = _inbound_units(inbound)
    snapshot_inventory = {
        key: InventoryPosition(
            sku=key[0],
            warehouse_id=key[1],
            on_hand=max(0, inventory[key]),
            in_transit=inbound_units.get(key, 0),
            allocated=0,
        )
        for key in inventory
    }
    snapshot_history = [
        DemandSeries(
            sku=series.sku,
            warehouse_id=series.warehouse_id,
            daily_units=_rolling_history(series.daily_units, demand_calendar[(series.sku, series.warehouse_id)], day),
        )
        for series in network.demand_history
    ]
    pool_supply = {
        sku: PoolSupply(
            sku=sku,
            available_units=max(pool.available_units, _forecast_supply_floor(network, sku)),
            reserved_units=pool.reserved_units,
        )
        for sku, pool in network.global_supply_pool.items()
    }
    return Network(
        service_level_z=network.service_level_z,
        skus=network.skus,
        warehouses=network.warehouses,
        lanes=network.lanes,
        inventory=snapshot_inventory,
        demand_history=snapshot_history,
        global_supply_pool=pool_supply,
        market_signals=network.market_signals,
        transport_options=network.transport_options,
        warehouse_constraints=network.warehouse_constraints,
        procurement_constraints=network.procurement_constraints,
    )


def _rolling_history(initial: list[int], actual: list[int], day: int) -> list[int]:
    history = initial + actual[:day]
    return history[-30:] if len(history) > 30 else history


def _forecast_supply_floor(network: Network, sku: str) -> int:
    total_recent = sum(sum(series.daily_units[-7:]) for series in network.demand_history if series.sku == sku)
    return max(100, total_recent * 3)


def _inbound_units(inbound: list[tuple[int, str, str, int, float]]) -> dict[tuple[str, str], int]:
    totals: dict[tuple[str, str], int] = {}
    for _, sku, warehouse_id, units, _ in inbound:
        key = (sku, warehouse_id)
        totals[key] = totals.get(key, 0) + units
    return totals


def _local_delivery_days(network: Network, warehouse_id: str) -> float:
    warehouse = network.warehouses[warehouse_id]
    return max(1.2, 3.0 - warehouse.last_mile_score)


def _fulfill_from_alternate_warehouses(
    network: Network,
    inventory: dict[tuple[str, str], int],
    sku_id: str,
    target_warehouse_id: str,
    required_units: int,
) -> tuple[int, float, float]:
    fulfilled = 0
    delivery_days = 0.0
    transfer_cost = 0.0
    candidates = sorted(
        (
            (key, units)
            for key, units in inventory.items()
            if key[0] == sku_id and key[1] != target_warehouse_id and units > 0
        ),
        key=lambda item: network.warehouses[item[0][1]].last_mile_score,
        reverse=True,
    )

    for key, units in candidates:
        if fulfilled >= required_units:
            break
        take = min(units, required_units - fulfilled)
        inventory[key] -= take
        fulfilled += take
        delivery_days += take * 5.5
        transfer_cost += take * 5.8

    return fulfilled, delivery_days, transfer_cost
